# WARNING: Under review - generated by LLM.

"""Public status cards and read-only KV-forked status queries.

Day 8 of Week 4: an operator may ask "what are you doing?" while an agent is
running.  The answer is a deterministic ``AgentStateCard`` derived only from
the durable event trace — never from hidden chain-of-thought — and, when a
KV/prefix fork is available, the status question is answered on a read-only
fork that is discarded without changing the main trace.

Invariants:

- the card contains only ledger-derived public state (goal, current action,
  approval state, last evidence, next safe step);
- the status fork is tool-disabled and read-only; closing it releases all
  branch pages and never mutates the main cache or workspace;
- steering is durable and queued; it never pretends the current generation
  was rewound.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

from .epoch import ApprovalEpoch, WorldStamp
from .prefix import ForkedPrefix, PrefixRegistry

if TYPE_CHECKING:
    from .session import SessionLog


@dataclass(frozen=True)
class AgentStateCard:
    """Deterministic public state derived only from the durable event trace."""

    goal: str
    current_action: str
    approval_state: str
    last_evidence: str
    next_safe_step: str
    checkpoint: str = ""
    phase: str = "running"

    def to_dict(self) -> dict[str, Any]:
        return {
            "goal": self.goal,
            "current_action": self.current_action,
            "approval_state": self.approval_state,
            "last_evidence": self.last_evidence,
            "next_safe_step": self.next_safe_step,
            "checkpoint": self.checkpoint,
            "phase": self.phase,
        }

    def render(self) -> str:
        """Render the card as plain text for display or a status query."""

        lines = [
            f"goal: {self.goal}",
            f"current action: {self.current_action}",
            f"approval: {self.approval_state}",
            f"last evidence: {self.last_evidence}",
            f"next safe step: {self.next_safe_step}",
            f"phase: {self.phase}",
        ]
        if self.checkpoint:
            lines.append(f"checkpoint: {self.checkpoint}")
        return "\n".join(lines)


def _latest_events(session: "SessionLog") -> tuple[Any, ...]:
    return session.events


def build_state_card(
    session: "SessionLog",
    *,
    approval_epoch: ApprovalEpoch | None = None,
    goal: str = "",
) -> AgentStateCard:
    """Derive a public state card from the durable event trace only.

    The card never requests or exposes hidden reasoning: every field is a
    function of recorded events and operator-provided approval state.
    """

    events = _latest_events(session)
    current_action = "idle"
    last_evidence = ""
    next_safe_step = "awaiting instruction"
    checkpoint = ""
    for event in events:
        if event.type == "tool_call":
            tool = event.data.get("tool", "?")
            arguments = event.data.get("arguments", {})
            current_action = f"{tool} {json.dumps(arguments, sort_keys=True)}"
            next_safe_step = "deliver tool result"
        elif event.type == "tool_result":
            content = event.data.get("content", "")
            if isinstance(content, str):
                last_evidence = content[:80]
            current_action = "observing tool result"
            next_safe_step = "continue the loop"
        elif event.type == "assistant_message":
            current_action = "generating"
            next_safe_step = "validate the action"
        elif event.type == "run_finished":
            phase = "finished" if event.data.get("completed") else "stopped"
            return AgentStateCard(
                goal=goal,
                current_action="none",
                approval_state=_approval_state(approval_epoch),
                last_evidence=last_evidence,
                next_safe_step="none",
                checkpoint=checkpoint,
                phase=phase,
            )
    return AgentStateCard(
        goal=goal,
        current_action=current_action,
        approval_state=_approval_state(approval_epoch),
        last_evidence=last_evidence,
        next_safe_step=next_safe_step,
        checkpoint=checkpoint,
    )


def _approval_state(approval: ApprovalEpoch | None) -> str:
    if approval is None:
        return "unknown"
    return f"epoch {approval.epoch}, writes " + (
        "enabled" if approval.allow_writes else "disabled"
    )


class StatusFork:
    """A read-only, tool-disabled status query fork over a KV prefix.

    The fork shares immutable prefix pages with the main run and carries no
    tool capability.  Answering a status question never appends to the main
    trace and never touches the workspace; closing the fork releases its
    shared references.
    """

    def __init__(
        self,
        registry: PrefixRegistry,
        fork: ForkedPrefix,
        *,
        tool_disabled: bool = True,
        world: WorldStamp,
        approval: ApprovalEpoch,
    ):
        if not tool_disabled:
            raise ValueError("status forks are always tool-disabled")
        self.registry = registry
        self.fork = fork
        self.world = world
        self.approval = approval
        self._closed = False

    @property
    def token_ids(self) -> tuple[int, ...]:
        return self.fork.token_ids

    def query(self, card: AgentStateCard, generate: Any) -> str:
        """Run one model status paraphrase on the fork.

        The card is the only model-visible state; the response is displayed
        and discarded.  The main trace, workspace, and main cache are
        untouched by construction.
        """

        if self._closed:
            raise RuntimeError("status fork is closed")
        messages = [
            {
                "role": "system",
                "content": (
                    "Answer with a short public status summary. "
                    "Do not reveal hidden reasoning. "
                    "You have no tools."
                ),
            },
            {
                "role": "user",
                "content": f"Current public state:\n{card.render()}",
            },
        ]
        return generate(messages)

    def close(self) -> None:
        if self._closed:
            return
        self.fork.close()
        self._closed = True


def open_status_fork(
    registry: PrefixRegistry,
    prefix_tokens: tuple[int, ...],
    *,
    world: WorldStamp,
    approval: ApprovalEpoch,
) -> StatusFork:
    """Open a read-only tool-disabled fork over the longest published prefix.

    The fork shares immutable pages with the main run; the caller answers a
    status question on it and then discards it with ``close``.  The main
    trace and workspace are never changed.
    """

    fork = registry.acquire(prefix_tokens)
    return StatusFork(
        registry,
        fork,
        tool_disabled=True,
        world=world,
        approval=approval,
    )
